mapper.select:
select g.id, g.code, g.name, g.description, g.status,
       ,
       g.created_at, g.updated_at, g.deleted_at, g.deleted_by
from identity_user_group g
where g.status in

  #{status}


  and (
    lower(g.code) like concat('%', lower(#{keyword}), '%')
    or lower(g.name) like concat('%', lower(#{keyword}), '%')
  )

order by g.created_at desc, g.id desc
limit #{limit}
offset #{offset}

select count(*) from identity_user_group g where g.status in
#{status}
and ( lower(g.code) like concat('%', lower(#{keyword}), '%') or lower(g.name) like concat('%', lower(#{keyword}), '%') )

mapper.insert:
insert into identity_user_group (
  code, name, description, status, created_at, updated_at
) values (
  #{code}, #{name}, #{description}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.sql:
g.id = #{groupId}
and g.status = 'ACTIVE'
and m.joined_at <= #{now}
and (m.expires_at is null or m.expires_at > #{now})
and u.status != 'DELETED'

  and (
    lower(coalesce(u.email, '')) like concat('%', lower(#{keyword}), '%')
    or lower(coalesce(u.display_name, '')) like concat('%', lower(#{keyword}), '%')
    or cast(u.id as text) = #{keyword}
  )

mapper.select:
select user_id, group_id, joined_at, expires_at, created_at, updated_at
from identity_user_group_membership
where group_id = #{groupId}
  and user_id in

  #{userId}

mapper.insert:
insert into identity_user_group_membership (
  user_id, group_id, joined_at, expires_at, created_at, updated_at
) values (
  #{userId}, #{groupId}, #{now}, #{expiresAt}, #{now}, #{now}
)
on conflict (user_id, group_id) do update
set joined_at = case
      when identity_user_group_membership.expires_at is not null
           and identity_user_group_membership.expires_at <= #{now}
        then #{now}
      else identity_user_group_membership.joined_at
    end,
    expires_at = #{expiresAt},
    updated_at = #{now}

mapper.delete:
delete from identity_user_group_membership
where group_id = #{groupId}
  and user_id = #{userId}

mapper.select:
select m.user_id, g.id as group_id, g.code, g.name, m.joined_at, m.expires_at from identity_user_group_membership m join identity_user_group g on g.id = m.group_id join auth_users u on u.id = m.user_id where m.user_id in
#{userId}
and g.status = 'ACTIVE' and m.joined_at <= #{now} and (m.expires_at is null or m.expires_at > #{now}) and u.status != 'DELETED' order by m.user_id, g.name, g.id
